"""PreToolUse guard for Claude Code: blocks edits of generated files and bypassing git hooks.

Reads the hook payload (JSON) from stdin. Exit code 2 blocks the tool call and shows the
message on stderr to Claude; anything else lets it through.
"""

import json
import re
import shlex
import sys

GENERATED = {
    "frontend/src/routeTree.gen.ts": "it is generated by the TanStack Router plugin (vite)",
    "frontend/src/api/schema.d.ts": "it is generated from the API: run `just gen-api`",
}
IGNORED_ON_PURPOSE = re.compile(r"^(\./)?(\.notes|data)(/|$)")


def check_edit(path: str) -> str | None:
    for generated, why in GENERATED.items():
        if path == generated or path.endswith("/" + generated):
            return f"Do not edit {generated} by hand: {why}."
    return None


GIT_OPTIONS_WITH_VALUE = {"-C", "-c", "--git-dir", "--work-tree", "--namespace", "--exec-path"}


def subcommand(words: list[str]) -> tuple[str, list[str]]:
    """Skip git's global options (`git -C repo commit ...`) and split off the subcommand."""
    i = 0
    while i < len(words) and words[i].startswith("-"):
        i += 2 if words[i] in GIT_OPTIONS_WITH_VALUE else 1
    return (words[i], words[i + 1 :]) if i < len(words) else ("", [])


def check_bash(command: str) -> str | None:
    # punctuation_chars splits `;`, `&&` and `|` off words (`core.hooksPath;` -> two tokens).
    lexer = shlex.shlex(command, posix=True, punctuation_chars=True)
    lexer.whitespace_split = True
    try:
        words = list(lexer)
    except ValueError:
        words = command.split()
    for i, word in enumerate(words):
        if word != "git":
            continue
        sub, args = subcommand(words[i + 1 :])
        if sub in ("commit", "push", "merge") and (
            "--no-verify" in args or (sub == "commit" and "-n" in args)
        ):
            return "Do not bypass the git hooks (--no-verify): fix what they report instead."
        forced = "-f" in args or "--force" in args
        if sub == "add" and forced and any(IGNORED_ON_PURPOSE.match(arg) for arg in args):
            return ".notes/ and data/ are gitignored on purpose and must never be committed."
        if sub == "config" and "core.hooksPath" in args:
            return "Do not change core.hooksPath: prek installs the hooks into .git/hooks."
    return None


def main() -> int:
    payload = json.load(sys.stdin)
    tool, data = payload.get("tool_name", ""), payload.get("tool_input", {})
    if tool == "Bash":
        problem = check_bash(data.get("command", ""))
    else:
        problem = check_edit(data.get("file_path", "") or data.get("notebook_path", ""))
    if problem:
        print(problem, file=sys.stderr)
        return 2
    return 0


if __name__ == "__main__":
    sys.exit(main())
